    if (!this._request) {
        callback();
        return;
    }

    if ((this._request as any)._writableState?.errored) {
        return;
    }
    // ... rest of the code safe now
});
```

This provides consistent null handling throughout the callback and eliminates the unsafe non-null assertion.

